function floorCompatible(p){return !p.floor||!currentFloor||String(p.floor).toLowerCase()===String(currentFloor).toLowerCase()}
function activePosition(){if(replayMode&&replayPos)return replayPos;if(clientTrack.smooth){let p={...clientTrack.smooth};const moving=Math.hypot(clientTrack.vel.x,clientTrack.vel.z)>.35;if($('predictive').checked&&state?.last_update&&moving){const age=clamp(nowSec()-state.last_update,0,Math.min(.35,Math.max(.12,(state.interval||.5)*.65)));p.x+=clientTrack.vel.x*age;p.y+=clientTrack.vel.y*age;p.z+=clientTrack.vel.z*age;$('predictionBadge').textContent=`PRED +${age.toFixed(2)}s`}else $('predictionBadge').textContent=(+$('smoothing').value||0)>0?'SMOOTH':'RAW';return p}return state?.position||null}
