function updateNav(){const p=activePosition();if(target?.map&&state?.map&&target.map!==state.map&&!replayMode){$('navName').textContent=target.name||'Questdoel';$('navDist').textContent='PLAN';$('routeDist').textContent='–';$('navDir').textContent=questMapName(target.map);$('navEta').textContent='Start raid';$('hudTarget').textContent=`Questplan: ${target.name} · ${questMapName(target.map)}`;return}ensureRoute();if(!target||!p){$('navName').textContent=target?.name||'Geen';$('navDist').textContent='–';$('routeDist').textContent='–';$('navDir').textContent='–';$('navEta').textContent='–';$('hudTarget').textContent='';return}const direct=dist(p,target),b=bearingTo(p,target),rd=routeDistance||direct,eta=rd/Math.max(speedMps>.4?speedMps:1.5,1);$('navName').textContent=target.name;$('navDist').textContent=Math.round(direct)+' m';$('routeDist').textContent=Math.round(rd)+' m';$('navDir').textContent=cardinal(b)+' '+Math.round(b)+'°';$('navEta').textContent=eta<60?Math.round(eta)+' s':Math.floor(eta/60)+'m '+Math.round(eta%60)+'s';$('hudTarget').textContent=`Doel: ${target.name} · ${Math.round(rd)}m · ${cardinal(b)}`}
