  $('autoMap').onchange=()=>saveCaptureInterval($('intervalRange').value);
  $('mapStyle').onchange=()=>{savePrefs();loadMap(mapKey());setTimeout(()=>{renderFilterControls();draw();renderDomPins()},60)};
  $('floorAuto').onchange=()=>{if(!$('floorAuto').checked)currentFloor=$('floorSelect').value;draw()};
  $('floorSelect').onchange=()=>{if(!$('floorAuto').checked){currentFloor=$('floorSelect').value;renderNearby();draw()}};
  $('intervalRange').oninput=()=>{$('intervalNumber').value=$('intervalRange').value;clearTimeout(intervalTimer);intervalTimer=setTimeout(async()=>{await saveCaptureInterval($('intervalRange').value);intervalTimer=null},160)};
  $('intervalNumber').onchange=()=>saveCaptureInterval($('intervalNumber').value);
