  document.querySelectorAll('[data-interval]').forEach(b=>b.onclick=()=>saveCaptureInterval(b.dataset.interval));

  $('followBtn').onclick=e=>{follow=!follow;e.currentTarget.classList.toggle('active',follow);e.currentTarget.textContent='Slim volgen: '+(follow?'AAN':'UIT');if(follow)setFollowView(true)};
  $('miniBtn').onclick=()=>{miniMode=!miniMode;document.body.classList.toggle('miniMode',miniMode);setTimeout(fitLayer,60)};
  $('resetBtn').onclick=()=>{trailWorld=[];showWholeMap()};
  $('navigatorBtn').onclick=()=>{navigatorMode=!navigatorMode;document.body.classList.toggle('navigatorMode',navigatorMode);setTimeout(fitLayer,60)};
  $('fullscreenBtn').onclick=async()=>{if(!document.fullscreenElement)await document.documentElement.requestFullscreen?.();else await document.exitFullscreen?.()};
  $('fitMapBtn').onclick=()=>showWholeMap();$('collapseLeftBtn').onclick=()=>setLeftClosed(true);$('openLeftBtn').onclick=()=>setLeftClosed(false);$('collapseRightBtn').onclick=()=>setRightClosed(true);$('openRightBtn').onclick=()=>setRightClosed(false);$('pinsHideAll').onclick=()=>setPinPreset('hide');$('pinsExtractOnly').onclick=()=>setPinPreset('extract');$('pinsQuestOnly').onclick=()=>setPinPreset('quest');$('pinsDefault').onclick=()=>setPinPreset('default');$('poiDetailClose').onclick=()=>{$('poiDetail').classList.add('hidden');generalSelectedPoi=null;draw()};
  [$('followZoom'),$('markerSize'),$('playerMarkerSize'),$('mapDim'),$('showTrail'),$('snapWalkable'),$('headingOffset'),$('predictive'),$('smoothing'),$('autoZoom'),$('useRoute'),$('showHeatmap')].forEach(el=>el.oninput=()=>{syncLabels();savePrefs();routeDirty=true;if($('showHeatmap').checked)loadHeatmapIfNeeded();if(follow&&activePosition())setFollowView();draw()});

  $('targetSelect').onchange=e=>setTargetValue(e.target.value);$('clearTarget').onclick=()=>{$('targetSelect').value='';setTargetValue('')};
  $('backtrackBtn').onclick=()=>{if(trailWorld.length){const p=trailWorld[0];target={...p,name:'Start van trail',_type:'backtrack'};routeDirty=true;updateNav();draw()}};
