  document.querySelectorAll('[data-editor]').forEach(b=>b.onclick=()=>setEditor(b.dataset.editor));
  $('clearBlocksBtn').onclick=()=>{if(confirm('Alle routeblokkades op deze map wissen?'))saveBlocked(new Set())};
  $('calibrateBtn').onclick=e=>{calibrationMode=!calibrationMode;e.currentTarget.classList.toggle('active',calibrationMode);e.currentTarget.textContent=calibrationMode?'Klik nu je echte positie':'Kalibratiemodus'};
  $('undoCalBtn').onclick=()=>{const a=anchors();a.pop();saveAnchors(a);draw()};$('clearCalBtn').onclick=()=>{localStorage.removeItem('eft-cal-v24-reemr-'+mapKey());renderCalibration();routeDirty=true;draw()};

  $('saveProfileBtn').onclick=()=>{const name=prompt('Naam van profiel:','Mijn raid profiel');if(!name)return;const a=profiles();a.push(snapshotProfile(name));saveProfiles(a)};
  $('applyProfileBtn').onclick=()=>applyProfile(profiles().find(p=>p.id===$('profileSelect').value));
  $('deleteProfileBtn').onclick=()=>{const id=$('profileSelect').value;if(!id)return;saveProfiles(profiles().filter(p=>p.id!==id))};

  $('questSelect').onchange=async()=>{await selectQuest($('questSelect').value);renderNearby();draw()};$('questFocus').onchange=()=>{renderNearby();draw()};$('questPins').onchange=()=>{hideQuestPopup();draw()};
  ['questSearch','questTrader','questMapFilter','questWithLocation'].forEach(id=>{const el=$(id);if(el)el.oninput=el.onchange=()=>renderQuestSelect()});
  $('refreshQuestsBtn').onclick=()=>loadQuestCatalog(true);$('clearQuestBtn').onclick=async()=>{$('questSelect').value='';await selectQuest('');if(state?.map&&mapKey()!==state.map){visualMapKey=state.map;$('map').value=state.map;loadMap(state.map)}};
  $('folderBtn').onclick=async()=>{await fetch('/api/redetect-folder',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});await refresh()};
  $('refreshDataBtn').onclick=async()=>{await fetch('/api/refresh-data',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});$('dataStatus').textContent='POI: verversen gestart...'};
