const productPalette=['#ffe45f','#58d8ff','#ff9d52','#76e69d','#d99cff','#ff6370','#5ce2d0','#f4a5d8'];
let renderedQuestHits=[], renderedClusters=[], planQuestDetails=new Map(), planQuestPois=[], raidPlanOrder=[], planStepIndex=0;
let questFocusMode=false;

function objectiveKindFromType(t){t=String(t||'').toLowerCase();if(t.includes('shoot')||t.includes('kill'))return'kill';if(t.includes('extract'))return'extract';if(t.includes('mark')||t.includes('plant')||t.includes('place')||t.includes('useitem'))return'mark';if(t.includes('key')||t.includes('door'))return'key';if(t.includes('item')||t.includes('pickup')||t.includes('find'))return'item';if(t.includes('visit')||t.includes('locate')||t.includes('zone')||t.includes('basic'))return'visit';return'visit'}
function objectiveStyle(p){const kind=objectiveKindFromType(p.objectiveType),m={visit:['#55cfff','◎'],item:['#66df91','▣'],mark:['#ffad4a','◆'],kill:['#ff5865','✕'],extract:['#35e0cd','⇥'],key:['#c490ff','⌑']}[kind]||['#ffe45f','•'];return{kind,color:p.planColor||m[0],glyph:m[1]}}
function confidenceForPoi(p){if(p.confidence)return p.confidence;if(Number.isFinite(p.x)&&Number.isFinite(p.z))return p.outline?.length?'zone':'exact';return'map'}
function confidenceText(c){return c==='exact'?'Exacte wereldpositie':c==='zone'?'Zone + exacte middenpositie':c==='approx'?'Benaderde locatie':'Alleen map bekend'}
function buildActiveQuestPois(){activeQuestPois=[];if(!activeQuest){renderQuestMapTabs();renderQuestMissionHud();buildRaidPlanPois();return}const done=questProgress(activeQuest.id);for(let oi=0;oi<(activeQuest.objectives||[]).length;oi++){const o=activeQuest.objectives[oi],locs=o.locations||[];for(let i=0;i<locs.length;i++){const l=locs[i];if(l.map!==mapKey()||!Number.isFinite(+l.x)||!Number.isFinite(+l.z))continue;activeQuestPois.push({id:`${activeQuest.id}:${o.id}:${i}`,name:o.description,shortLabel:'QUEST',category:'quest',questActive:true,questId:activeQuest.id,questName:activeQuest.name,questTrader:activeQuest.trader,objectiveId:o.id,objectiveIndex:oi,objectiveType:o.type||'objective',objectiveDescription:o.description,requirements:o.requirements||[],optional:!!o.optional,markerNumber:oi+1,done:done.has(o.id),x:+l.x,y:+l.y||0,z:+l.z,level:l.level??null,floor:l.level??null,outline:l.outline||null,confidence:l.outline?.length?'zone':'exact',locationIndex:i,map:l.map})}}renderTargetSelect();renderQuestMapTabs();renderQuestMissionHud();buildRaidPlanPois()}

function raidPlanIds(){try{return JSON.parse(localStorage.getItem('eft-v18-raid-plan')||'[]')}catch{return[]}}
function saveRaidPlanIds(ids){ids=[...new Set(ids)].slice(0,8);localStorage.setItem('eft-v18-raid-plan',JSON.stringify(ids));renderRaidPlan();loadRaidPlanDetails()}
async function loadRaidPlanDetails(){const ids=raidPlanIds();for(const id of ids){if(planQuestDetails.has(id))continue;try{const d=await(await fetch('/api/quest?id='+encodeURIComponent(id),{cache:'no-store'})).json();if(d.quest)planQuestDetails.set(id,d.quest)}catch{}}buildRaidPlanPois();renderRaidPlan();draw()}
function buildRaidPlanPois(){planQuestPois=[];const ids=raidPlanIds();ids.forEach((qid,qi)=>{const q=planQuestDetails.get(qid);if(!q)return;const prog=questProgress(qid);(q.objectives||[]).forEach((o,oi)=>{if(prog.has(o.id))return;(o.locations||[]).forEach((l,li)=>{if(l.map!==mapKey()||!Number.isFinite(+l.x)||!Number.isFinite(+l.z))return;if(activeQuest?.id===qid)return;planQuestPois.push({id:`plan:${qid}:${o.id}:${li}`,name:o.description,category:'quest',questActive:true,planQuest:true,questId:qid,questName:q.name,questTrader:q.trader,objectiveId:o.id,objectiveIndex:oi,objectiveType:o.type||'objective',objectiveDescription:o.description,requirements:o.requirements||[],markerNumber:oi+1,planColor:productPalette[qi%productPalette.length],x:+l.x,y:+l.y||0,z:+l.z,level:l.level??null,floor:l.level??null,outline:l.outline||null,confidence:l.outline?.length?'zone':'exact',locationIndex:li,map:l.map})})})});renderTargetSelect()}
