function drawQuestLayer(){renderedQuestHits=[];renderedClusters=[];const pins=[...activeQuestPois,...(($('showPlanPins')?.checked)?planQuestPois:[])].filter(p=>poiVisible(p));drawQuestZones(pins);const groups=questPinGroups(pins);const selectedId=questSelectedPoi?.id;for(const g of groups){if(g.pins.length>1){const xs=g.pins.map(p=>toP(worldNormalizedRaw(p.x,p.z)).x),ys=g.pins.map(p=>toP(worldNormalizedRaw(p.x,p.z)).y),q={x:xs.reduce((a,b)=>a+b,0)/xs.length,y:ys.reduce((a,b)=>a+b,0)/ys.length},r=14/zoom;ctx.save();ctx.fillStyle='#11181c';ctx.beginPath();ctx.arc(q.x,q.y,r*1.25,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#ffe45f';ctx.lineWidth=3/zoom;ctx.stroke();ctx.fillStyle='#fff';ctx.font=`900 ${Math.max(10,13/zoom)}px Segoe UI`;ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(String(g.pins.length),q.x,q.y);ctx.restore();renderedClusters.push({pins:g.pins,screen:screenFromLayer(q)});continue}const p=g.pins[0],q=toP(worldNormalizedRaw(p.x,p.z)),sel=selectedId===p.id,hov=questHoverPoi?.id===p.id,r=drawPinShape(q,p,sel,hov),scr=screenFromLayer(q);renderedQuestHits.push({p,screen:scr,r:Math.max(18,r*zoom)});const mode=$('pinLabels')?.value||'smart';if(mode!=='off'&&(sel||hov||(mode==='smart'&&zoom>2.65))){const st=objectiveStyle(p),label=`${p.markerNumber}. ${String(p.objectiveDescription||p.name).slice(0,42)}`;ctx.font=`800 ${Math.max(8,10/zoom)}px Segoe UI`;const tw=ctx.measureText(label).width+10/zoom;let lx=q.x+r+7/zoom,ly=q.y-12/zoom;ctx.fillStyle='rgba(4,8,10,.90)';ctx.fillRect(lx,ly,tw,18/zoom);ctx.strokeStyle=st.color;ctx.lineWidth=1/zoom;ctx.strokeRect(lx,ly,tw,18/zoom);ctx.fillStyle='#edf2f4';ctx.textAlign='left';ctx.textBaseline='alphabetic';ctx.fillText(label,lx+5/zoom,ly+12/zoom)}}ctx.textAlign='start';ctx.textBaseline='alphabetic'}
