async function showQuestPopup(p,ev=null){
  if(!p)return;
  if(p.questId&&activeQuest?.id!==p.questId){
    $('questSelect').value=p.questId;
    await selectQuest(p.questId);
    p=activeQuestPois.find(x=>String(x.objectiveId)===String(p.objectiveId)&&x.locationIndex===p.locationIndex)||p;
  }
  questSelectedPoi=p;
  const q=activeQuest,o=(q?.objectives||[]).find(x=>String(x.id)===String(p.objectiveId));
  if(!q||!o)return;
  hideQuestPopup();
  showObjectiveDrawer(p,o,q);
  draw();
}

function showObjectiveDrawer(p,o,q){
  const d=$('objectiveDrawer'),c=$('objectiveDrawerContent'),st=objectiveStyle(p),conf=confidenceForPoi(p);
  const objectiveReq=[...(o.requirements||[])];
  const fallbackReq=objectiveReq.length?[]:[...(q.requirements||[])].slice(0,4);
  const req=objectiveReq.length?objectiveReq:fallbackReq;
  const done=questProgress(q.id).has(o.id);
  c.innerHTML=`<div class="drawerType" style="color:${st.color}">${escapeHtml(st.glyph)} ${escapeHtml(st.kind.toUpperCase())} · PIN ${p.markerNumber}</div><div class="drawerTitle"><span style="color:${st.color}">${escapeHtml(o.description)}</span></div><div class="drawerQuest">${escapeHtml(q.name)} · ${escapeHtml(q.trader||'Unknown')}</div><div class="drawerDo"><b>Wat moet je doen?</b><br>${escapeHtml(objectiveHint(o))}</div>${req.length?`<div class="qpopReq"><b>${objectiveReq.length?'Voor dit doel nodig':'Raid-kit / mogelijk nodig'}:</b><br>${req.map(requirementLabel).map(escapeHtml).join('<br>')}</div>`:''}<div class="drawerMeta"><span>${escapeHtml(questMapName(p.map))}</span>${p.level!==null&&p.level!==undefined?`<span>${escapeHtml(String(p.level).replaceAll('_',' '))}</span>`:''}<span>${escapeHtml(confidenceText(conf))}</span></div><div class="drawerActions"><button id="drawerNavigate" class="primaryPinAction">▶ Navigeer</button><button id="drawerDone">${done?'✓ Voltooid':'Afvinken'}</button></div>`;
  d.classList.remove('hidden');
  $('drawerNavigate').onclick=()=>navigateQuestLocation(o.id,p.locationIndex);
  $('drawerDone').onclick=()=>{const set=questProgress(q.id);set.has(o.id)?set.delete(o.id):set.add(o.id);saveQuestProgress(q.id,set);buildActiveQuestPois();renderQuestCard();renderRaidPlan();d.classList.add('hidden');questSelectedPoi=null;draw()};
}


function renderQuestPrep(){const b=$('questPrepSummary');if(!b)return;if(!activeQuest){b.innerHTML='';return}const req=activeQuest.requirements||[],kit=questKit(activeQuest.id),done=req.filter((_,i)=>kit.has(String(i))).length,open=(activeQuest.objectives||[]).filter(o=>!questProgress(activeQuest.id).has(o.id)).length;b.innerHTML=`<div class="prepHero"><b>Raid voorbereiding</b>${req.length?`${done}/${req.length} benodigdheden afgevinkt · `:''}${open} open objectives${req.length?`<br>${req.slice(0,4).map(requirementLabel).map(escapeHtml).join(' · ')}`:''}</div>`}

