function buildPlanCandidates(){const rows=[];const ids=raidPlanIds();ids.forEach((qid,qi)=>{const q=planQuestDetails.get(qid);if(!q)return;const prog=questProgress(qid);(q.objectives||[]).forEach((o,oi)=>{if(prog.has(o.id))return;(o.locations||[]).forEach((l,li)=>{if(l.map===mapKey()&&Number.isFinite(+l.x)&&Number.isFinite(+l.z))rows.push({qid,q,o,oi,l,li,color:productPalette[qi%productPalette.length]})})})});return rows}
