function globalSearchRows(q){q=q.trim().toLowerCase();if(!q)return[];const rows=[],seen=new Set();const addPoi=(p,sub)=>{const k=`${p.map||mapKey()}|${p.name||''}|${Math.round((+p.x||0)*10)}|${Math.round((+p.z||0)*10)}`;if(seen.has(k))return;seen.add(k);rows.push({type:'poi',label:p.name,sub,p})};for(const p of globalPoiIndex){if((p.name||'').toLowerCase().includes(q))addPoi(p,`${p.category||'POI'} · ${questMapName(p.map)}`)}for(const p of allPois()){if((p.name||'').toLowerCase().includes(q))addPoi({...p,map:p.map||mapKey()},`${p.category} · ${questMapName(mapKey())}`)}for(const w of waypoints())if((w.name||'').toLowerCase().includes(q))addPoi({...w,map:w.map||mapKey()},`Waypoint · ${questMapName(w.map||mapKey())}`);for(const qs of questCatalog){if((qs.searchText||qs.name||'').toLowerCase().includes(q))rows.push({type:'quest',label:qs.name,sub:`${qs.trader} · ${(qs.maps||[]).map(questMapName).join(', ')}`,q:qs})}return rows.slice(0,24)}
