  $('globalSearch').oninput=renderGlobalSearch;$('globalSearch').onkeydown=e=>{if(e.key==='Escape')$('searchResults').classList.add('hidden')};
  $('findMeBtn').onclick=()=>{if(state?.map&&mapKey()!==state.map){questPlanLocked=false;visualMapKey=state.map;$('map').value=state.map;loadMap(state.map)}follow=true;$('followBtn').classList.add('active');$('followBtn').textContent='Slim volgen: AAN';setFollowView(true)};
  $('captureEnabled').onchange=async()=>{await fetch('/api/settings',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({interval_seconds:+$('intervalNumber').value||1,capture_enabled:$('captureEnabled').checked,auto_map_detect:$('autoMap').checked})});await refresh()};
  $('diagnosticsBtn').onclick=openDiagnostics;$('diagnosticsClose').onclick=()=>$('diagnosticsModal').classList.add('hidden');$('diagnosticsCopy').onclick=()=>navigator.clipboard?.writeText($('diagnosticsText').textContent||'');$('updateAllBtn').onclick=async()=>{await fetch('/api/update-all',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});$('diagnosticsText').textContent+='\n\nUpdate gestart.'};
  $('addQuestPlanBtn').onclick=()=>{const id=activeQuest?.id||$('questSelect').value;if(!id)return;const ids=raidPlanIds();if(!ids.includes(id))ids.push(id);saveRaidPlanIds(ids)};$('optimizePlanBtn').onclick=optimizeRaidPlan;$('clearPlanBtn').onclick=()=>{raidPlanOrder=[];planQuestDetails.clear();saveRaidPlanIds([])};
  $('pinDensity').onchange=()=>{draw();renderDomPins()};$('pinLabels').onchange=renderDomPins;if($('showPlanPins'))$('showPlanPins').onchange=()=>{draw();renderDomPins()};$('questFocusModeBtn').onclick=()=>{questFocusMode=!questFocusMode;document.body.classList.toggle('questFocusMode',questFocusMode);setTimeout(fitLayer,60)};
  await loadRaidPlanDetails();renderRaidPlan();renderQuestPrep();
  setInterval(updateProductHealth,500);
