// ---------------------------------------------------------------------------
// v24 DOM PIN ENGINE — one interactive pin layer for EVERY map.
// Pins stay a fixed readable screen size, remain clickable while panning/zooming,
// support hover labels, click details, filters and lightweight clustering.
// ---------------------------------------------------------------------------
function pinNormalized(p){return poiMapNormalized(p)}
function pinScreen(p){const n=pinNormalized(p);if(!n)return null;return screenFromLayer(toP(n))}
function pinColor(p){if(p.questActive)return questObjectiveDone(p)?'#62d785':'#ffc83d';return catColor[p.category]||'#eaf0f3'}
function pinGlyph(p){if(p.questActive)return String(p.markerNumber||'Q');return generalSymbol(p.category)}
function domPinVisible(p){if(p.questActive&&$('questPins')&&!$('questPins').checked)return false;return poiVisible(p)}
function domPinList(){let pins=allPois().filter(domPinVisible).filter(p=>pinNormalized(p));const mode=$('pinDensity')?.value||'auto';if(mode==='minimal')pins=pins.filter(p=>p.questActive||p.category==='extract'||p.category==='transit'||p===generalSelectedPoi);return pins.slice(0,1200)}
function clusterDomPins(pins){if(($('pinDensity')?.value||'auto')!=='auto'||zoom>=1.55||pins.length<35)return pins.map(p=>({pins:[p],single:p}));const critical=pins.filter(p=>p.questActive||p.category==='extract'||p.category==='transit'||p===generalSelectedPoi||p===questSelectedPoi),regular=pins.filter(p=>!critical.includes(p)),cells=new Map(),size=48;for(const p of regular){const s=pinScreen(p);if(!s)continue;const key=`${Math.round(s.x/size)},${Math.round(s.y/size)}`;if(!cells.has(key))cells.set(key,[]);cells.get(key).push(p)}return[...[...cells.values()].map(a=>a.length===1?{pins:a,single:a[0]}:{pins:a}),...critical.map(p=>({pins:[p],single:p}))]}
function renderDomPins(){const layerPins=$('domPins');if(!layerPins||!viewport||!baseW||!baseH)return;const vr=viewport.getBoundingClientRect();const groups=clusterDomPins(domPinList());const frag=document.createDocumentFragment();for(const g of groups){let p=g.single,s;if(p)s=pinScreen(p);else{const scr=g.pins.map(pinScreen).filter(Boolean);if(!scr.length)continue;s={x:scr.reduce((a,b)=>a+b.x,0)/scr.length,y:scr.reduce((a,b)=>a+b.y,0)/scr.length}}if(!s||s.x<-40||s.y<-40||s.x>vr.width+40||s.y>vr.height+40)continue;const b=document.createElement('button');b.type='button';const catClass=p?.category?` pin-${String(p.category).replace(/[^a-z0-9_-]/gi,'')}`:'';b.className='domMapPin'+catClass+(p?.questActive?' questPin':'')+(p&&questObjectiveDone(p)?' done':'')+(p&&((generalSelectedPoi&&generalSelectedPoi.id===p.id)||(questSelectedPoi&&questSelectedPoi.id===p.id))?' selected':'')+(!p?' cluster':'');b.style.left=s.x+'px';b.style.top=s.y+'px';b.style.setProperty('--pin',p?pinColor(p):'#ffe66a');const label=p?(p.name||p.objectiveDescription||'POI'):`${g.pins.length} pins`;b.innerHTML=`<span class="pinHead"></span><span class="pinGlyph">${escapeHtml(p?pinGlyph(p):String(g.pins.length))}</span><span class="pinLabel">${escapeHtml(label)}</span>`;b.title=label;b.onpointerdown=e=>{e.stopPropagation()};b.onclick=e=>{e.preventDefault();e.stopPropagation();if(!p){fitPinSet(g.pins.filter(x=>Number.isFinite(+x.x)&&Number.isFinite(+x.z)));if(!g.pins.some(x=>Number.isFinite(+x.x)&&Number.isFinite(+x.z))){zoom=Math.min(5,zoom*1.65);const n=g.pins.map(pinNormalized).filter(Boolean),cx=n.reduce((a,q)=>a+q.x,0)/n.length,cy=n.reduce((a,q)=>a+q.y,0)/n.length,q=toP({x:cx,y:cy}),sc=fitScale*zoom;panX=-(q.x-baseW/2)*sc;panY=-(q.y-baseH/2)*sc;updateTransform();draw()}return}if(p.questActive){questSelectedPoi=p;showQuestPopup(p,e)}else showPoiDetail(p)};b.onmouseenter=e=>{if(p)showPoiTip(e,p)};b.onmousemove=e=>{if(p)showPoiTip(e,p)};b.onmouseleave=hidePoiTip;const labelMode=$('pinLabels')?.value||'selected';if(p&&(labelMode==='smart'&&zoom>2.35))b.classList.add('showLabel');frag.appendChild(b)}layerPins.replaceChildren(frag);updatePinCount()}

